UPDATE player_match_stats SET damage = 0 WHERE damage IS NULL;
ALTER TABLE player_match_stats ALTER COLUMN damage SET NOT NULL;
ALTER TABLE player_match_stats ALTER COLUMN damage SET DEFAULT 0;

